window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-9d39a5de69cd75d7"]={"versions": [{"id": "FIG-9d39a5de69cd75d7", "releases": ["R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Signalverlaufs- und Timing-Diagramm (zeitdiskrete/kontinuierliche Trajektorien koppelnder Regelgrößen über einer synchronen Zeitachse).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform, Domäne <em>Powertrain</em> (Spezifikation: <code>AUTOSAR_ApplicationInterfaces_Explanation_Powertrain</code>, Release R3.0.7).</li>\n<li><strong>Funktionaler Zweck:</strong> Modellierung der zweipfadigen Drehmomentstruktur (<em>Torque-Based Engine Management</em>) für Ottomotoren. Veranschaulichung der Entkopplung von trägem Füllungspfad (Drosselklappe/Luft) und hochdynamischem Wirkungsgradpfad (Zündwinkel) zur Bereitstellung einer sofort abrufbaren Drehmomentreserve (<em>Torque Reserve</em>) bei gleichzeitig konstantem Ist-Moment (<em>Torque Realised</em>).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Beteiligte Software-Komponenten (SW-Cs):</strong></li>\n<li><code>TorqueCoordinator_SWC</code>: Koordiniert externe Momentenanforderungen (z. B. von Getriebesteuerung, ESP/ASR) und zerlegt diese in langsame (<em>Slow</em>) und schnelle (<em>Fast</em>) Sollwerte.</li>\n<li><code>AirPathControl_SWC</code>: Wandelt den <code>Slow Torque request</code> in eine Füllungsgröße (<code>Requested Air Charge</code>) und steuert das Drosselklappen- bzw. Ladedruckstellglied an.</li>\n<li><code>IgnitionControl_SWC</code>: Berechnet anhand der tatsächlichen Füllung (<code>Delivered Air Charge</code>) und des <code>Fast Torque request</code> den notwendigen Zündwinkelrückzug (<code>Actual Ignition</code>).</li>\n<li><strong>Schnittstellen & Port-Elemente (Sender-Receiver-Kommunikation via RTE):</strong></li>\n<li><code>Slow Torque request</code> (<code>SenderReceiverInterface</code>): Niederfrequente Drehmomentanforderung an den Luftpfad inkl. Vorhaltemoment (Reserve).</li>\n<li><code>Fast Torque request</code> (<code>SenderReceiverInterface</code>): Hochfrequente, zylindersynchrone Drehmomentanforderung, die das unmittelbar an der Kurbelwelle wirksame Moment bestimmt.</li>\n<li><code>Torque \"Reserve\" Requested</code>: Differenzsignal $\\Delta M = M_{\\text{slow}} - M_{\\text{fast}}$.</li>\n<li><code>Requested Air Charge</code> vs. <code>Delivered Air Charge</code>: Soll- vs. Ist-Zylinderfrischluftmasse (Modellierung der Saugrohrdynamik mit Tiefpass-/PT1-Verhalten).</li>\n<li><code>Base Ignition</code> vs. <code>Actual Ignition</code>: Zündzeitpunkt für optimalen Wirkungsgrad ($\\eta_{\\text{opt}}$) vs. nach spät verstellter Zündwinkel ($\\eta < 1$).</li>\n<li><code>Torque Reserve Available</code>: Realisierte Momentenreserve im Zylinder, definiert über das Wirkungsgraddefizit $\\Delta \\eta_{\\text{ign}} = f(\\text{Base Ignition} - \\text{Actual Ignition})$.</li>\n<li><code>Torque Realised</code>: Das resultierende indizierte/effektive Drehmoment.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Stationärer Ausgangszustand ($t < t_1$):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Slow Torque request</code> = <code>Fast Torque request</code>.</li>\n<li><code>Requested Air Charge</code> = <code>Delivered Air Charge</code>.</li>\n<li><code>Actual Ignition</code> = <code>Base Ignition</code> (optimaler thermodynamischer Wirkungsgrad).</li>\n<li><code>Torque Realised</code> entspricht exakt der Anforderung.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Aufbau der Drehmomentreserve ($t_1 \\le t < t_2$):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Trigger:</em> Anforderung einer Drehmomentreserve (z. B. durch Getriebeschaltvorbereitung, Leerlaufregler oder Katalysatorheizung).</li>\n<li><code>Slow Torque request</code> springt stufenförmig nach oben; <code>Fast Torque request</code> verharrt auf Basissollwert.</li>\n<li><code>Requested Air Charge</code> springt synchron zum langsamen Momentensollwert.</li>\n<li><code>Delivered Air Charge</code> folgt asymmetrisch/asymptotisch verzögert (PT1-Saugrohrfüllverzögerung).</li>\n<li><strong>Kompensation im Zündpfad:</strong> Proportional zum Anstieg der Füllung wird <code>Actual Ignition</code> stetig nach <em>spät</em> (Wirkungsgradverschlechterung) verstellt.</li>\n<li><strong>Ergebnis:</strong> <code>Torque Realised</code> bleibt vollkommen isobar/flach auf dem Niveau des <code>Fast Torque request</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Stationäre Reservephase ($t_2 \\le t < t_3$):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Delivered Air Charge</code> erreicht stationäres Maximum.</li>\n<li>Maximale <code>Torque Reserve Available</code> ist aufgebaut. Ein sprunghafter Anstieg des <code>Fast Torque request</code> könnte nun innerhalb eines einzigen Arbeitstakts durch Vorverlegung der Zündung auf <code>Base Ignition</code> umgesetzt werden.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Abbau der Reserve ($t_3 \\le t < t_4$):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Slow Torque request</code> fällt sprunghaft auf das Niveau des <code>Fast Torque request</code> zurück.</li>\n<li><code>Requested Air Charge</code> bricht sofort ein; <code>Delivered Air Charge</code> klingt verzögert ab (Saugrohrentleerung).</li>\n<li><code>Actual Ignition</code> wird simultan von <em>spät</em> zurück auf <code>Base Ignition</code> herangeführt.</li>\n<li><code>Torque Realised</code> bleibt während der gesamten Entleerungsphase unverändert konstant.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Task-Scheduling & Abtastraten (RTE/OS-Ebene):</strong></li>\n<li><strong>Luftpfad:</strong> Verarbeitung in zeitgesteuerten periodischen Tasks (z. B. 10 ms oder 20 ms Rate).</li>\n<li><strong>Zündpfad:</strong> Zwingende Ausführung in zylindersegment- bzw. winkelsynchronen Tasks (Event-getriggert über Kurbelwellengeber / Complex Device Driver <code>CDD</code>), um Zyklus-für-Zyklus-Jitter bei der Momentenkompensation zu verhindern.</li>\n<li><strong>RTE-Datenkonsistenz:</strong></li>\n<li>Zwischen <code>AirPathControl_SWC</code> und <code>IgnitionControl_SWC</code> muss zwingend kohärente Datenhaltung gewährleistet sein (Verwendung von impliziten Lese-/Schreibzugriffen <code>Rte_IRead</code> / <code>Rte_IWrite</code> innerhalb der Segment-Tasks zur Vermeidung von Schwebungs- und Drehmomentenschlägen an der Kurbelwelle).</li>\n<li><strong>Systemgrenzen & Diagnose (Dem/Det):</strong></li>\n<li><strong>Thermische Limitierung:</strong> Dauerhafte Zündwinkelspätverstellung treibt die Abgastemperaturen massiv in die Höhe. Applikations-SWCs müssen integrierende Überwachungsfunktionen (Katalysatorschutzzeitglieder) vorsehen, die bei thermischer Überlast die Reserve zwangsweise abbauen.</li>\n<li><strong>Verzögerungszeitkompensation:</strong> Der Zündpfad muss das gemessene bzw. über das Saugrohrmodell geschätzte <code>Delivered Air Charge</code>-Signal prädiktiv kompensieren, da fehlerhafte Phasenlagen zwischen Füllungsanstieg und Zündwinkelrückzug zu transienten Momentenspitzen führen.</li>\n</ul>"}, {"id": "FIG-f6147f4d6a2b830f", "releases": ["R3.1.5", "R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Signalverlaufs- und Timing-Diagramm (zeitdiskrete/kontinuierliche Trajektorien koppelnder Regelgrößen über einer synchronen Zeitachse).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform, Domäne <em>Powertrain</em> (Spezifikation: <code>AUTOSAR_ApplicationInterfaces_Explanation_Powertrain</code>, Release R3.0.7).</li>\n<li><strong>Funktionaler Zweck:</strong> Modellierung der zweipfadigen Drehmomentstruktur (<em>Torque-Based Engine Management</em>) für Ottomotoren. Veranschaulichung der Entkopplung von trägem Füllungspfad (Drosselklappe/Luft) und hochdynamischem Wirkungsgradpfad (Zündwinkel) zur Bereitstellung einer sofort abrufbaren Drehmomentreserve (<em>Torque Reserve</em>) bei gleichzeitig konstantem Ist-Moment (<em>Torque Realised</em>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Beteiligte Software-Komponenten (SW-Cs):</strong></li>\n<li><code>TorqueCoordinator_SWC</code>: Koordiniert externe Momentenanforderungen (z. B. von Getriebesteuerung, ESP/ASR) und zerlegt diese in langsame (<em>Slow</em>) und schnelle (<em>Fast</em>) Sollwerte.</li>\n<li><code>AirPathControl_SWC</code>: Wandelt den <code>Slow Torque request</code> in eine Füllungsgröße (<code>Requested Air Charge</code>) und steuert das Drosselklappen- bzw. Ladedruckstellglied an.</li>\n<li><code>IgnitionControl_SWC</code>: Berechnet anhand der tatsächlichen Füllung (<code>Delivered Air Charge</code>) und des <code>Fast Torque request</code> den notwendigen Zündwinkelrückzug (<code>Actual Ignition</code>).</li>\n<li><strong>Schnittstellen & Port-Elemente (Sender-Receiver-Kommunikation via RTE):</strong></li>\n<li><code>Slow Torque request</code> (<code>SenderReceiverInterface</code>): Niederfrequente Drehmomentanforderung an den Luftpfad inkl. Vorhaltemoment (Reserve).</li>\n<li><code>Fast Torque request</code> (<code>SenderReceiverInterface</code>): Hochfrequente, zylindersynchrone Drehmomentanforderung, die das unmittelbar an der Kurbelwelle wirksame Moment bestimmt.</li>\n<li><code>Torque \"Reserve\" Requested</code>: Differenzsignal $\\Delta M = M_{\\text{slow}} - M_{\\text{fast}}$.</li>\n<li><code>Requested Air Charge</code> vs. <code>Delivered Air Charge</code>: Soll- vs. Ist-Zylinderfrischluftmasse (Modellierung der Saugrohrdynamik mit Tiefpass-/PT1-Verhalten).</li>\n<li><code>Base Ignition</code> vs. <code>Actual Ignition</code>: Zündzeitpunkt für optimalen Wirkungsgrad ($\\eta_{\\text{opt}}$) vs. nach spät verstellter Zündwinkel ($\\eta < 1$).</li>\n<li><code>Torque Reserve Available</code>: Realisierte Momentenreserve im Zylinder, definiert über das Wirkungsgraddefizit $\\Delta \\eta_{\\text{ign}} = f(\\text{Base Ignition} - \\text{Actual Ignition})$.</li>\n<li><code>Torque Realised</code>: Das resultierende indizierte/effektive Drehmoment.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Stationärer Ausgangszustand ($t < t_1$):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Slow Torque request</code> = <code>Fast Torque request</code>.</li>\n<li><code>Requested Air Charge</code> = <code>Delivered Air Charge</code>.</li>\n<li><code>Actual Ignition</code> = <code>Base Ignition</code> (optimaler thermodynamischer Wirkungsgrad).</li>\n<li><code>Torque Realised</code> entspricht exakt der Anforderung.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Aufbau der Drehmomentreserve ($t_1 \\le t < t_2$):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Trigger:</em> Anforderung einer Drehmomentreserve (z. B. durch Getriebeschaltvorbereitung, Leerlaufregler oder Katalysatorheizung).</li>\n<li><code>Slow Torque request</code> springt stufenförmig nach oben; <code>Fast Torque request</code> verharrt auf Basissollwert.</li>\n<li><code>Requested Air Charge</code> springt synchron zum langsamen Momentensollwert.</li>\n<li><code>Delivered Air Charge</code> folgt asymmetrisch/asymptotisch verzögert (PT1-Saugrohrfüllverzögerung).</li>\n<li><strong>Kompensation im Zündpfad:</strong> Proportional zum Anstieg der Füllung wird <code>Actual Ignition</code> stetig nach <em>spät</em> (Wirkungsgradverschlechterung) verstellt.</li>\n<li><strong>Ergebnis:</strong> <code>Torque Realised</code> bleibt vollkommen isobar/flach auf dem Niveau des <code>Fast Torque request</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Stationäre Reservephase ($t_2 \\le t < t_3$):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Delivered Air Charge</code> erreicht stationäres Maximum.</li>\n<li>Maximale <code>Torque Reserve Available</code> ist aufgebaut. Ein sprunghafter Anstieg des <code>Fast Torque request</code> könnte nun innerhalb eines einzigen Arbeitstakts durch Vorverlegung der Zündung auf <code>Base Ignition</code> umgesetzt werden.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Abbau der Reserve ($t_3 \\le t < t_4$):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Slow Torque request</code> fällt sprunghaft auf das Niveau des <code>Fast Torque request</code> zurück.</li>\n<li><code>Requested Air Charge</code> bricht sofort ein; <code>Delivered Air Charge</code> klingt verzögert ab (Saugrohrentleerung).</li>\n<li><code>Actual Ignition</code> wird simultan von <em>spät</em> zurück auf <code>Base Ignition</code> herangeführt.</li>\n<li><code>Torque Realised</code> bleibt während der gesamten Entleerungsphase unverändert konstant.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Task-Scheduling & Abtastraten (RTE/OS-Ebene):</strong></li>\n<li><strong>Luftpfad:</strong> Verarbeitung in zeitgesteuerten periodischen Tasks (z. B. 10 ms oder 20 ms Rate).</li>\n<li><strong>Zündpfad:</strong> Zwingende Ausführung in zylindersegment- bzw. winkelsynchronen Tasks (Event-getriggert über Kurbelwellengeber / Complex Device Driver <code>CDD</code>), um Zyklus-für-Zyklus-Jitter bei der Momentenkompensation zu verhindern.</li>\n<li><strong>RTE-Datenkonsistenz:</strong></li>\n<li>Zwischen <code>AirPathControl_SWC</code> und <code>IgnitionControl_SWC</code> muss zwingend kohärente Datenhaltung gewährleistet sein (Verwendung von impliziten Lese-/Schreibzugriffen <code>Rte_IRead</code> / <code>Rte_IWrite</code> innerhalb der Segment-Tasks zur Vermeidung von Schwebungs- und Drehmomentenschlägen an der Kurbelwelle).</li>\n<li><strong>Systemgrenzen & Diagnose (Dem/Det):</strong></li>\n<li><strong>Thermische Limitierung:</strong> Dauerhafte Zündwinkelspätverstellung treibt die Abgastemperaturen massiv in die Höhe. Applikations-SWCs müssen integrierende Überwachungsfunktionen (Katalysatorschutzzeitglieder) vorsehen, die bei thermischer Überlast die Reserve zwangsweise abbauen.</li>\n<li><strong>Verzögerungszeitkompensation:</strong> Der Zündpfad muss das gemessene bzw. über das Saugrohrmodell geschätzte <code>Delivered Air Charge</code>-Signal prädiktiv kompensieren, da fehlerhafte Phasenlagen zwischen Füllungsanstieg und Zündwinkelrückzug zu transienten Momentenspitzen führen.</li>\n</ul>"}], "trans": [{"from": "FIG-9d39a5de69cd75d7", "to": "FIG-f6147f4d6a2b830f", "fr": "R3.0.7", "tr": "R3.1.5", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
